mapper.select:
SELECT log_id AS logId,request_id AS requestId,provider_code AS providerCode,
       adapter_code AS adapterCode,operation_code AS operationCode,success AS success,
       gateway_error_code AS gatewayErrorCode,provider_error_code AS providerErrorCode,
       message,retryable,elapsed_ms AS elapsedMs,call_time AS callTime,create_time AS createTime
FROM ticket_source_gateway_log
WHERE 1=1

    AND provider_code=#{providerCode}


    AND operation_code=#{operationCode}


    AND success=#{success}

ORDER BY log_id DESC
LIMIT #{limit}
